import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hyzen_pharmd/app/providers.dart';
import 'package:hyzen_pharmd/features/academics/domain/models.dart';
import 'package:hyzen_pharmd/features/academics/domain/study_tree.dart';
import 'package:hyzen_pharmd/features/academics/data/study_tree_provider.dart';
import 'package:hyzen_pharmd/features/content/data/content_providers.dart';
import 'package:hyzen_pharmd/features/downloads/domain/download_record.dart';
import 'package:hyzen_pharmd/features/downloads/domain/download_browser.dart';
import 'package:hyzen_pharmd/features/search/data/search_index.dart';

Map<String,dynamic> file(String id, {bool published = true}) => {
  'id':id, 'title':'$id.pdf', 'pdfUrl':'https://example.org/$id.pdf', 'published':published,
};
List<Map<String,dynamic>> fixture() => [
  {'id':'y1','label':'1st Professional','semesters':[]},
  {'id':'y2','label':'2nd Professional','semesters':[
    {'id':'s','label':'Semester 1','subjects':[
      {'id':'subject','label':'Pharmacology','sections':[
        {'id':'section','title':'Study Notes','topics':[
          {'id':'topic','title':'Diabetes','files':[file('insulin'),file('hidden',published:false)],'folders':[
            {'id':'extra / α','title':'Extra','files':[file('details')],'folders':[
              {'id':'deep','title':'Deep','files':[file('reference')]},
              {'id':'private','title':'Unpublished','published':false,'files':[file('private')]},
            ]},
          ]},
        ]},
      ]},
    ]},
  ]},
];
void main() {
  test('Mixed files/folders recurse and preserve legacy IDs/publication', () {
    final tree = StudyTree.parse(LibraryKind.notes, fixture());
    final trail = tree.resolve(['y2','s','subject','section','topic'])!;
    expect(trail.last.files.single.id, 'insulin');
    expect(trail.last.children.single.id, 'extra / α');
    expect(trail.last.fileCount, 3);
    expect(tree.resolve(['y2','s','subject','section','topic','extra / α','deep'])!.last.files.single.id, 'reference');
    expect(tree.resolve(['y2','s','subject','section','topic','extra / α','private']), isNull);
    expect(tree.resolve(['moved']), isNull);
  });
  test('Year scoping and deep query locations do not expose other years', () {
    final tree = StudyTree.parse(LibraryKind.notes, fixture());
    expect(tree.forYear(2).roots.single.id, 'y2');
    expect(tree.forYear(1).roots.single.id, 'y1');
    expect(tree.forYear(5).roots, isEmpty);
    expect(tree.forYear(2,admin:true).roots.length, 2);
    final uri = Uri.parse(studyLocation(LibraryKind.notes, ['y2','s','subject','section','topic','extra / α','deep']));
    expect(uri.path, '/study/notes/y2/s/subject/section/topic');
    expect(uri.queryParametersAll['folder'], ['extra / α','deep']);
  });
  test('Legacy topic normalization does not duplicate subjects or files', () {
    final raw = [{'id':'y','label':'2nd Professional','semesters':[
      {'id':'s','label':'S1','subjects':[
        {'id':'su','label':'Pharmacy','topics':[{'id':'old','title':'Legacy','pdfUrl':'https://example.org/old.pdf'}]},
      ]},
    ]}];
    final tree = StudyTree.parse(LibraryKind.notes, raw);
    expect(tree.fileCount, Library.parse(LibraryKind.notes, raw).fileCount);
    expect(tree.fileCount, 1);
  });
  test('Recursive search covers filenames and paths, never invented PDF text', () {
    final index = buildStudyIndex(StudyTree.parse(LibraryKind.notes, fixture()).forYear(2));
    expect(runSearch(index,'reference').single.trail.last, 'Deep');
    expect(runSearch(index,'private'), isEmpty);
    expect(runSearch(index,'text-only-inside-pdf'), isEmpty);
  });
  test('Saved hierarchy is virtual, status filters preserve paused and missing records', () {
    DownloadRecord r(String key, DownloadStatus state, {String? path}) => DownloadRecord(key:key, kind:LibraryKind.notes,
      title:key, sourceUrl:'https://example.org/$key.pdf', status:state, localPath:path,
      trail:['2nd Professional','Semester 1','Pharmacology']);
    final saved = r('saved',DownloadStatus.ready,path:'/private/original.pdf');
    final records = [saved,r('paused',DownloadStatus.paused),r('failed',DownloadStatus.failed),r('missing',DownloadStatus.ready)];
    expect(records.where((r)=>matchesSavedView(r,SavedView.saved)).length,1);
    expect(records.where((r)=>matchesSavedView(r,SavedView.progress)).length,1);
    expect(records.where((r)=>matchesSavedView(r,SavedView.failed)).length,2);
    expect(browseDownloads(records,[]).folders,{'Notes':4});
    expect(browseDownloads(records,['Notes','2nd Professional','Semester 1','Pharmacology']).files.length,4);
    expect(browseDownloads(records,['Other']).files,isEmpty);
    expect(saved.localPath,'/private/original.pdf');
    expect(browseDownloads(records,[],grouped:false).files.length,4);
  });
  test('Changing profile-year provider re-scopes cached parsed tree', () async {
    final year = StateProvider<int>((_) => 2);
    final tree = StudyTree.parse(LibraryKind.notes, fixture());
    final container = ProviderContainer(overrides:[
      professionalYearProvider.overrideWith((ref) => ref.watch(year)),
      isAdminProvider.overrideWithValue(false),
      parsedStudyTreeProvider(LibraryKind.notes).overrideWith((_) async => Loaded(tree,fromCache:true)),
    ]);
    addTearDown(container.dispose);
    await container.read(parsedStudyTreeProvider(LibraryKind.notes).future);
    expect(container.read(studyTreeProvider(LibraryKind.notes)).requireValue.data.roots.single.id,'y2');
    container.read(year.notifier).state=1;
    expect(container.read(studyTreeProvider(LibraryKind.notes)).requireValue.data.roots.single.id,'y1');
  });
}

test/download_lifecycle_test.dart:
import 'dart:async';
import 'dart:io';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hive_flutter/hive_flutter.dart';
import 'package:hyzen_pharmd/core/storage/local_store.dart';
import 'package:hyzen_pharmd/features/academics/domain/models.dart';
import 'package:hyzen_pharmd/features/downloads/data/downloads_controller.dart';
import 'package:hyzen_pharmd/features/downloads/data/file_store.dart';
import 'package:hyzen_pharmd/features/downloads/data/file_store_io.dart' as io_store;
import 'package:hyzen_pharmd/features/downloads/domain/download_record.dart';

class TestStore implements FileStore {
  @override
  Future<void> discardPartial(String key) async {}
  final transfer = Completer<DownloadedFile>();
  final started = Completer<void>();
  int calls = 0;
  final deleted = <String>[];
  bool cleared = false;
  @override
  bool get supported => true;
  @override
  Future<DownloadedFile> download(
    String url,
    String key,
    ProgressCb progress, {
    bool Function()? cancelled,
  }) {
    calls++;
    if (!started.isCompleted) started.complete();
    return transfer.future;
  }

  @override
  Future<DownloadedFile> importPreview(String path, String key) =>
      Future.value(DownloadedFile(path, 0));

  @override
  Future<bool> exists(String path) async => true;
  @override
  Future<void> delete(String path) async {
    deleted.add(path);
  }

  @override
  Future<void> clearAll() async {
    cleared = true;
  }
}

void main() {
  late Directory temp;
  setUp(() async {
    temp = await Directory.systemTemp.createTemp('hyzen-download-test-');
    Hive.init(temp.path);
    await Hive.openBox<String>(Boxes.downloads);
  });
  tearDown(() async {
    await Hive.close();
    await temp.delete(recursive: true);
  });
  const file = FileRef(
    kind: LibraryKind.notes,
    title: 'Notes',
    url: 'https://example.org/a.pdf',
  );
  test('simultaneous saves share one transfer', () async {
    final store = TestStore();
    final container = ProviderContainer(
      overrides: [fileStoreProvider.overrideWithValue(store)],
    );
    addTearDown(container.dispose);
    final ctrl = container.read(downloadsProvider.notifier);
    final first = ctrl.save(file), second = ctrl.save(file);
    expect(identical(first, second), isTrue);
    await store.started.future;
    expect(store.calls, 1);
    store.transfer.complete(const DownloadedFile('/private/a.pdf', 50));
    await first;
    expect(container.read(downloadsProvider).values.single.isReady, isTrue);
  });
  test('delete during transfer cannot recreate metadata or file', () async {
    final store = TestStore();
    final container = ProviderContainer(
      overrides: [fileStoreProvider.overrideWithValue(store)],
    );
    addTearDown(container.dispose);
    final ctrl = container.read(downloadsProvider.notifier);
    final transfer = ctrl.save(file);
    final failure = expectLater(transfer, throwsException);
    await store.started.future;
    final key = container.read(downloadsProvider).keys.single;
    final removing = ctrl.remove(key);
    store.transfer.complete(const DownloadedFile('/private/a.pdf', 50));
    await removing;
    await failure;
    expect(store.deleted, contains('/private/a.pdf'));
    expect(container.read(downloadsProvider), isEmpty);
    expect(JsonBox(Boxes.downloads).values(), isEmpty);
  });
  test('clear all settles active transfers before clearing storage', () async {
    final store = TestStore();
    final container = ProviderContainer(
      overrides: [fileStoreProvider.overrideWithValue(store)],
    );
    addTearDown(container.dispose);
    final ctrl = container.read(downloadsProvider.notifier);
    final transfer = ctrl.save(file);
    final failure = expectLater(transfer, throwsException);
    await store.started.future;
    final clearing = ctrl.removeAll();
    store.transfer.complete(const DownloadedFile('/private/a.pdf', 50));
    await clearing;
    await failure;
    expect(store.cleared, isTrue);
    expect(container.read(downloadsProvider), isEmpty);
  });
  test('Saved file and metadata survive store/controller restart without network', () async {
    final original = File('${temp.path}/original.pdf');
    await original.writeAsString('%PDF-1.4\nlocal fixture\n%%EOF');
    final saved = DownloadRecord(key:'saved', kind:LibraryKind.notes, title:'Notes', sourceUrl:'https://example.org/a.pdf',
      status:DownloadStatus.ready, localPath:original.path, trail:['2nd Professional','Pharmacology']);
    await JsonBox(Boxes.downloads).put(saved.key,saved.toMap());
    final first=ProviderContainer(overrides:[fileStoreProvider.overrideWithValue(io_store.createFileStore(testDirectory:temp))]);
    expect(first.read(downloadsProvider).values.single.localPath,original.path);
    first.dispose();
    await Hive.close(); await Hive.openBox<String>(Boxes.downloads);
    final second=ProviderContainer(overrides:[fileStoreProvider.overrideWithValue(io_store.createFileStore(testDirectory:temp))]);
    addTearDown(second.dispose);
    final restored=second.read(downloadsProvider).values.single;
    expect(restored.isReady,isTrue); expect(restored.trail,saved.trail);
    expect(await File(restored.localPath!).readAsString(),'%PDF-1.4\nlocal fixture\n%%EOF');
  });
  test('Missing saved file becomes retryable rather than falsely ready', () async {
    final saved=DownloadRecord(key:'missing',kind:LibraryKind.notes,title:'Missing',sourceUrl:'https://example.org/a.pdf',
      status:DownloadStatus.ready,localPath:'${temp.path}/gone.pdf');
    await JsonBox(Boxes.downloads).put(saved.key,saved.toMap());
    final container=ProviderContainer(overrides:[fileStoreProvider.overrideWithValue(io_store.createFileStore(testDirectory:temp))]);
    addTearDown(container.dispose);
    final failed=Completer<void>();
    final subscription=container.listen(downloadsProvider,(_,next) {
      if(next['missing']?.status==DownloadStatus.failed && !failed.isCompleted) failed.complete();
    },fireImmediately:true);
    addTearDown(subscription.close);
    await failed.future.timeout(const Duration(seconds:5));
    await Hive.box<String>(Boxes.downloads).flush();
    expect(container.read(downloadsProvider)['missing']!.isReady,isFalse);
    expect(container.read(downloadsProvider)['missing']!.error,contains('missing'));
  });

}

test/study_preview_test.dart:
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';
import 'package:flutter_test/flutter_test.dart';
import 'package:http/http.dart' as http;

import 'package:hyzen_pharmd/features/academics/data/study_preview_io.dart';

final png = base64Decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR4nGNgqC/7DwADbQH1vXeWcAAAAABJRU5ErkJggg==');
class OversizeClient extends http.BaseClient {
  @override
  Future<http.StreamedResponse> send(http.BaseRequest request) async =>
    http.StreamedResponse(const Stream.empty(),200,contentLength:20000000);
}
void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  late Directory temp; late File pdf;
  setUp(() async {
    temp=await Directory.systemTemp.createTemp('study-preview-');
    pdf=File('${temp.path}/source.pdf'); await pdf.writeAsString('%PDF-1.4\nfixture\n%%EOF');
  });
  tearDown(() async { await temp.delete(recursive:true); });
  test('Local preview deduplicates, caches across repository restart, isolates versions', () async {
    var renders=0;
    Future<Uint8List> render(String path) async { expect(path,pdf.path); renders++; return png; }
    final dir=Directory('${temp.path}/cache');
    final repo=StudyPreviewRepository(directory:dir,render:render);
    final results=await Future.wait([
      repo.load('https://example.org/a.pdf',localPath:pdf.path,version:'user-a:v1'),
      repo.load('https://example.org/a.pdf',localPath:pdf.path,version:'user-a:v1'),
    ]);
    expect(results.first,png); expect(renders,1);
    final restarted=StudyPreviewRepository(directory:dir,render:render);
    await restarted.load('https://example.org/a.pdf',localPath:pdf.path,version:'user-a:v1');
    expect(renders,1);
    await restarted.load('https://example.org/a.pdf',localPath:pdf.path,version:'user-b:v1');
    expect(renders,2);
    expect(await pdf.exists(),isTrue);
    expect(await pdf.readAsString(),'%PDF-1.4\nfixture\n%%EOF');
  });
  test('Corrupt preview cache regenerates without deleting its source', () async {
    var renders=0; final dir=Directory('${temp.path}/cache');
    final repo=StudyPreviewRepository(directory:dir,render:(_) async { renders++; return png; });
    await repo.load('https://example.org/a.pdf',localPath:pdf.path);
    final cached=await dir.list().where((f)=>f.path.endsWith('.png')).cast<File>().first;
    await cached.writeAsString('not an image');
    final restarted=StudyPreviewRepository(directory:dir,render:(_) async { renders++; return png; });
    await restarted.load('https://example.org/a.pdf',localPath:pdf.path);
    expect(renders,2); expect(await pdf.exists(),isTrue);
  });
  test('Clearing previews leaves saved originals intact and permits regeneration', () async {
    var renders=0;
    final dir=Directory('${temp.path}/cache');
    final repo=StudyPreviewRepository(directory:dir,render:(_) async { renders++; return png; });
    await repo.load('https://example.org/a.pdf',localPath:pdf.path);
    await repo.clear();
    expect(await dir.list().where((f)=>f is File && f.path.endsWith('.png')).toList(),isEmpty);
    expect(await pdf.exists(),isTrue);
    await repo.load('https://example.org/a.pdf',localPath:pdf.path);
    expect(renders,2);
  });
  test('Oversized remote preview is rejected without rendering or keeping a partial', () async {
    var rendered=false; final dir=Directory('${temp.path}/cache');
    final repo=StudyPreviewRepository(directory:dir,
      clientFactory:()=>OversizeClient(),
      render:(_) async { rendered=true; return png; });
    await expectLater(repo.load('https://example.org/large.pdf'),throwsA(predicate((e)=>e.toString().contains('too large'))));
    expect(rendered,isFalse);
    final leftovers=await dir.list(recursive:true).where((f)=>f is File && f.path.endsWith('.part')).toList();
    expect(leftovers,isEmpty);
    expect(await pdf.exists(),isTrue);
  });
}

