typedef StudyPreviewLoader = Future<Uint8List> Function(String url, {String? localPath, String? version});
final studyPreviewLoaderProvider = Provider<StudyPreviewLoader>((_) => StudyPreviewRepository.instance.load);

class StudyBrowserScreen extends ConsumerStatefulWidget {
  const StudyBrowserScreen({super.key, required this.kind, required this.path});
  final LibraryKind kind;
  final List<String> path;
  @override
  ConsumerState<StudyBrowserScreen> createState() => _StudyBrowserScreenState();
}
class _StudyBrowserScreenState extends ConsumerState<StudyBrowserScreen> {
  String _query = '';
  String? _location;
  @override
  void didUpdateWidget(covariant StudyBrowserScreen old) {
    super.didUpdateWidget(old);
    if (old.kind != widget.kind || old.path.join('/') != widget.path.join('/')) _query = '';
  }
  @override
  Widget build(BuildContext context) {
    final state = ref.watch(studyTreeProvider(widget.kind));
    final enabled = ref.watch(sectionEnabledProvider(widget.kind.sectionId));
    final loaded = state.valueOrNull;
    final extra = GoRouterState.of(context).uri.queryParametersAll['folder'] ?? const <String>[];
    var ids = [...widget.path, ...extra];
    final tree = loaded?.data;
    // Saved year already scopes roots. Skip a redundant sole year/semester.
    if (ids.isEmpty && tree?.roots.length == 1) {
      final year = tree!.roots.single; ids = [year.id];
      if (year.children.length == 1 && year.children.single.role == 'semesters' && year.files.isEmpty) {
        ids.add(year.children.single.id);
      }
    }
    final location = ids.join('\u001f');
    if (_location != location) { _location = location; _query = ''; }
    final trail = tree?.resolve(ids);
    final current = trail?.lastOrNull;
    final folders = current?.children ?? tree?.roots ?? const <StudyNode>[];
    final files = current?.files ?? const <StudyFile>[];
    final q = _query.trim().toLowerCase();
    final visibleFolders = folders.where((n) => q.isEmpty || n.title.toLowerCase().contains(q)).toList();
    final visibleFiles = files.where((f) => q.isEmpty || f.title.toLowerCase().contains(q)).toList();
    Future<void> refresh() => refreshContent(ref, [widget.kind.storageKey]);
    Widget empty(String title, String message) => SliverFillRemaining(hasScrollBody: false,
      child: EmptyState(icon: Icons.folder_outlined, illustration: 'empty', title: title, message: message));
    return TabPage(
      title: current?.title ?? widget.kind.title,
      subtitle: '${widget.kind.shortTitle} · Browse study materials', onRefresh: refresh,
      slivers: [
        if (!enabled) empty('Temporarily unavailable', 'This library has been hidden by the admin.')
        else if (state.hasError && loaded == null) SliverFillRemaining(hasScrollBody: false,
          child: ErrorState(message: 'Could not load this library.', onRetry: refresh))
        else if (loaded == null) const SliverToBoxAdapter(child: Padding(padding: EdgeInsets.all(20), child: SkeletonList(count: 5)))
        else if (trail == null) empty('Not found', 'This folder was moved or unpublished.')
        else ...[
          SliverPadding(padding: const EdgeInsets.symmetric(horizontal: HSpace.screen),
            sliver: SliverToBoxAdapter(child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
              if (loaded.fromCache) const OfflineHint(),
              Wrap(spacing: 2, runSpacing: 2, children: [
                TextButton(onPressed: () => context.go('/study'), child: const Text('Study')),
                TextButton(onPressed: () => context.push(studyLocation(widget.kind, [])), child: Text(widget.kind.shortTitle)),
                for (var i = 0; i < trail.length; i++)
                  TextButton(onPressed: i == trail.length - 1 ? null : () => context.push(studyLocation(widget.kind, ids.take(i + 1).toList())),
                    child: Text(trail[i].title)),
              ]),
              Text('${folders.length} folders · ${files.length} files', style: Theme.of(context).textTheme.bodySmall),
              const SizedBox(height: 8),
              HSearchField(key: ValueKey(ids.join('/')), hint: 'Find a folder or filename here',
                onChanged: (value) => setState(() => _query = value)),
              const SizedBox(height: 12),
            ])),
          ),
          if (visibleFolders.isEmpty && visibleFiles.isEmpty)
            empty(q.isEmpty ? 'No files yet' : 'No matches', q.isEmpty ? 'Published materials will appear here.' : 'Try another folder or filename.')
          else ...[
            if (visibleFolders.isNotEmpty)
              SliverPadding(padding: const EdgeInsets.symmetric(horizontal: HSpace.screen),
                sliver: visibleFolders.every((n) => n.role == 'subjects')
                  ? SliverList.builder(itemCount: visibleFolders.length, itemBuilder: (context,i) {
                      final node = visibleFolders[i];
                      return ResourceTile(icon: Icons.science_rounded, color: Theme.of(context).colorScheme.primary,
                        title: node.title, subtitle: '${node.fileCount} files',
