import 'models.dart';

/// Read-only adapter over existing hierarchy keys plus additive `folders/files`.
/// No remote data is rewritten and all observed legacy IDs are retained.
class StudyNode {
  const StudyNode({required this.id, required this.title, required this.role,
    this.children = const [], this.files = const []});
  final String id, title, role;
  final List<StudyNode> children;
  final List<StudyFile> files;
  int get fileCount => files.length + children.fold<int>(0, (n, c) => n + c.fileCount);
}

class StudyTree {
  const StudyTree(this.kind, this.roots);
  final LibraryKind kind;
  final List<StudyNode> roots;
  int get fileCount => roots.fold<int>(0, (n, c) => n + c.fileCount);
  StudyTree forYear(int? year, {bool admin = false}) => admin || year == null ? this
    : StudyTree(kind, roots.where((n) => (professionalNumber(n.title) ?? professionalNumber(n.id)) == year).toList());
  List<StudyNode>? resolve(List<String> ids) {
    var children = roots;
    final trail = <StudyNode>[];
    for (final id in ids) {
      final node = children.where((n) => n.id == id).firstOrNull;
      if (node == null) return null;
      trail.add(node); children = node.children;
    }
    return trail;
  }
  factory StudyTree.parse(LibraryKind kind, Object? raw) {
    final normalized = kind == LibraryKind.papers ? normalizePastPapers(raw) : ensureNestedTree(raw, kind);
    var budget = 10000;
    List<StudyNode> nodes(Object? value, String role, int depth) {
      if (value is! List || depth > 128 || budget <= 0) return [];
      final maps = value.whereType<Map>().where((m) => m['published'] != false && m['published'] != 'false').toList();
      final positions = {for (var i = 0; i < maps.length; i++) maps[i]: i};
      int order(Map m) => m['order'] is num ? (m['order'] as num).toInt() : int.tryParse('${m['order'] ?? 0}') ?? 0;
      maps.sort((a,b) { final c = order(a).compareTo(order(b)); return c != 0 ? c : positions[a]!.compareTo(positions[b]!); });
      final result = <StudyNode>[];
      for (var i = 0; i < maps.length && budget > 0; i++) {
        budget--;
        final m = maps[i];
        final title = '${m['label'] ?? m['title'] ?? 'Folder'}';
        final children = <StudyNode>[];
        // Legacy MCQ/Notes normalisation retains old topics as well as synthesised
        // sections: choose its primary hierarchy once, avoiding duplicate entries.
        for (final key in ['semesters','subjects','sections','topics']) {
          if (m[key] is List && (m[key] as List).isNotEmpty) {
            children.addAll(nodes(m[key], key, depth + 1)); break;
          }
        }
        children.addAll(nodes(m['folders'], 'folders', depth + 1));
        final files = <StudyFile>[];
        if (m['files'] is List) {
          for (final f in (m['files'] as List).whereType<Map>()) {
            final parsed = StudyFile.fromMap(Map<String,dynamic>.from(f));
            if (parsed != null && parsed.url.isNotEmpty) files.add(parsed);
          }
          files.sort((a,b) => a.order.compareTo(b.order));
        }
        result.add(StudyNode(id: '${m['id'] ?? '${role}_$i'}', title: title, role: role, children: children, files: files));
      }
      return result;
    }
    return StudyTree(kind, nodes(normalized, 'years', 0));
  }
}

String studyLocation(LibraryKind kind, List<String> ids) {
  final base = '/study/${kind.name}${ids.take(5).map((id) => '/${Uri.encodeComponent(id)}').join()}';
  final extra = ids.skip(5).toList();
  return extra.isEmpty ? base : '$base?${Uri(queryParameters: {'folder': extra}).query}';
}

