                ),
              ),
              const Gap(HSpace.md),
              PanelBlock(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text('Storage', style: t.textTheme.titleMedium),
                    const Gap(HSpace.sm),
                    Text(
                      'Offline files: ${formatBytes(used)}',
                      style: t.textTheme.bodyMedium,
