                    if (kIsWeb)
                      Text(
                        'Save Offline is available in the Android app.',
                        style: t.textTheme.bodySmall,
                      ),
                    const Gap(HSpace.sm),
                    Wrap(
                      spacing: 8,
                      runSpacing: 8,
                      children: [
                        OutlinedButton.icon(
                          icon: const Icon(Icons.cleaning_services_rounded),
                          label: const Text('Clear content cache'),
                          onPressed: () async {
                            await JsonBox(Boxes.contentCache).clear();
                            for (final key in publicContentKeys) {
                              forcedRefresh.add(key);
                              ref.invalidate(contentProvider(key));
                            }
                            if (context.mounted) {
                              showHSnack(
                                context,
                                'Cache cleared. Content will reload.',
                              );
                            }
                          },
                        ),
                        OutlinedButton.icon(
                          icon: const Icon(Icons.cleaning_services_rounded),
                          label: const Text('Clear PDF previews'),
                          onPressed: () async {
                            try {
                              await StudyPreviewRepository.instance.clear();
                              if (context.mounted) showHSnack(context, 'Preview cache cleared');
                            } catch (_) {
                              if (context.mounted) showHSnack(context, 'Could not clear previews. Please retry.', error: true);
                            }
                          },
                        ),
                        OutlinedButton.icon(
                          icon: const Icon(Icons.history_rounded),
                          label: const Text('Clear history'),
                          onPressed: () async {
                            await ref.read(recentProvider.notifier).clear();
                            if (context.mounted) {
                              showHSnack(context, 'History cleared');
                            }
                          },
                        ),
                        OutlinedButton.icon(
                          icon: const Icon(Icons.folder_open_rounded),
                          label: const Text('Manage downloads'),
                          onPressed: () => context.go('/downloads'),
                        ),
                      ],
                    ),
                  ],
                ),
              ),
              const Gap(HSpace.md),
              ResourceTile(
                icon: Icons.description_rounded,
                color: HColors.ink2,
                title: 'Terms of Use',
                onTap: () => context.push('/legal/terms'),
              ),
              ResourceTile(
                icon: Icons.privacy_tip_rounded,
                color: HColors.ink2,
                title: 'Privacy Policy',
                onTap: () => context.push('/legal/privacy'),
              ),
              ResourceTile(
                icon: Icons.info_rounded,
                color: HColors.primary,
                title: 'About ${Brand.shortName}',
                subtitle:
                    '${Brand.appName} · v${ref.watch(appVersionProvider).valueOrNull ?? '1.3.3'}',
                onTap: () => context.push('/about'),
              ),
              const Gap(HSpace.sm),
              HButton(
                label: 'Log out',
                icon: Icons.logout_rounded,
                outlined: true,
                onPressed: () => logout(context, ref),
              ),
            ],
          ),
        ),
      ],
    );
  }
}
